from opentrons import protocol_api

metadata = {
    'protocolName': 'Salt-Ligand Template [[REPLICATES]]',
    'author': 'Lab 167',
    'description': "Template OT-2 protocol with placeholders for salts and ligands; templatable for 2.19",
}
requirements = {"robotType": "OT-2", "apiLevel": "2.19"}


def run(protocol: protocol_api.ProtocolContext):
    # Deck setup: slots
    tiprack_slot4 = protocol.load_labware(load_name="opentrons_96_tiprack_300ul", location=4)
    tiprack_slot7 = protocol.load_labware(load_name="opentrons_96_tiprack_300ul", location=7)
    tiprack_slot10 = protocol.load_labware(load_name="opentrons_96_tiprack_300ul", location=10)

    p300s = protocol.load_instrument(instrument_name="p300_single_gen2", mount="right", tip_racks=[tiprack_slot4, tiprack_slot10])
    p300m = protocol.load_instrument(instrument_name="p300_multi_gen2", mount="left", tip_racks=[tiprack_slot7])

    try:
        src_lab = protocol.load_labware(load_name="cytiva_96_filterwellplate_1ml", location=1)
    except Exception:
        protocol.comment('WARNING: custom labware not found; using nest plate as fallback.')
        src_lab = protocol.load_labware(load_name="nest_96_wellplate_200ul_flat", location=1)

    reservoir0 = protocol.load_labware(load_name="nest_12_reservoir_15ml", location=5)
    reservoir1 = protocol.load_labware(load_name="nest_12_reservoir_15ml", location=9)
    reservoir2 = protocol.load_labware(load_name="nest_12_reservoir_15ml", location=8)
    reservoir3 = protocol.load_labware(load_name="nest_12_reservoir_15ml", location=6)
    reservoir4 = protocol.load_labware(load_name="nest_12_reservoir_15ml", location=3)
    mixing_plate = protocol.load_labware(load_name="nest_96_wellplate_2ml_deep", location=11)

    REPLICATES = '[[REPLICATES]]'
    TOTAL_VOLUME = '[[TOTAL_VOLUME]]'
    SALT_CONCENTRATIONS = '[[SALT_CONCENTRATIONS]]'
    LIGAND_CONCENTRATIONS = '[[LIGAND_CONCENTRATIONS]]'
    SALT_STOCK_CONCENTRATION = '[[SALT_STOCK_CONCENTRATION]]'
    LIGAND_STOCK_CONCENTRATION = '[[LIGAND_STOCK_CONCENTRATION]]'
    NUMBER_OF_SALT_CONCENTRATIONS = '[[NUMBER_OF_SALT_CONCENTRATIONS]]'
    NUMBER_OF_LIGAND_CONCENTRATIONS = '[[NUMBER_OF_LIGAND_CONCENTRATIONS]]'

    def _is_placeholder(v):
        return isinstance(v, str) and v.startswith('[[')

    def _parse_int(v, default):
        if _is_placeholder(v):
            return default
        try:
            return int(v)
        except Exception:
            return default

    def _parse_float(v, default):
        if _is_placeholder(v):
            return default
        try:
            return float(v)
        except Exception:
            return default

    def _parse_float_list(v, default):
        if _is_placeholder(v):
            return default
        if v is None:
            return default
        if isinstance(v, (list, tuple)):
            try:
                return [float(x) for x in v]
            except Exception:
                return default
        if isinstance(v, str):
            parts = [p.strip() for p in v.split(';') if p.strip() != '']
            try:
                return [float(p) for p in parts]
            except Exception:
                return default
        return default

    def _parse_int_from(v, default):
        if _is_placeholder(v):
            return default
        try:
            return int(v)
        except Exception:
            return default

    salt_list = _parse_float_list(SALT_CONCENTRATIONS, default=[0.0])
    ligand_list = _parse_float_list(LIGAND_CONCENTRATIONS, default=[0.0])
    replicates = _parse_int(REPLICATES, default=8)
    num_salt = _parse_int_from(NUMBER_OF_SALT_CONCENTRATIONS, default=len(salt_list))
    num_ligand = _parse_int_from(NUMBER_OF_LIGAND_CONCENTRATIONS, default=len(ligand_list))
    stock_salt = _parse_float(SALT_STOCK_CONCENTRATION, default=1.0)
    stock_ligand = _parse_float(LIGAND_STOCK_CONCENTRATION, default=1.0)
    total_vol = _parse_float(TOTAL_VOLUME, default=1000.0)

    if salt_list is None:
        salt_list = [0.0]
    if ligand_list is None:
        ligand_list = [0.0]

    # Step 2: Populate Reservoir 3 wells with 10 mL each (from high/low salt) - simplified
    max_step2 = min(replicates, 12, len(salt_list))
    if max_step2 > 0:
        p300m.pick_up_tip()
        for i in range(max_step2):
            conc = salt_list[i] if i < len(salt_list) else 0.0
            total_well_vol = 10000.0
            high_total = total_well_vol * (conc / stock_salt) if stock_salt > 0 else 0.0
            if high_total > total_well_vol:
                high_total = total_well_vol
            low_total = total_well_vol - high_total
            high_per = high_total / 8.0
            low_per = low_total / 8.0
            dest = reservoir3.wells()[i]
            high_src = reservoir2.wells()[min(6+i, len(reservoir2.wells())-1)]
            low_src = reservoir0.wells()[i]
            if high_per > 0:
                p300m.transfer(high_per, high_src, dest, new_tip='never')
            if low_per > 0:
                p300m.transfer(low_per, low_src, dest, new_tip='never')
        p300m.drop_tip()

    # Step 3: For each salt conc, fill Reservoir 4 well with 10 mL at 2x conc (split between two sources)
    max_step3 = min(len(salt_list), 12)
    if max_step3 > 0:
        p300m.pick_up_tip()
        for i in range(max_step3):
            conc = salt_list[i] if i < len(salt_list) else 0.0
            total_well_vol = 10000.0
            high_total = total_well_vol * (2.0 * conc / stock_salt) if stock_salt > 0 else 0.0
            if high_total > total_well_vol:
                high_total = total_well_vol
            low_total = total_well_vol - high_total
            high_per = high_total / 8.0
            low_per = low_total / 8.0
            dest = reservoir4.wells()[i]
            high_src = reservoir2.wells()[min(6+i, len(reservoir2.wells())-1)]
            low_src = reservoir0.wells()[i]
            if high_per > 0:
                p300m.transfer(high_per, high_src, dest, new_tip='never')
            if low_per > 0:
                p300m.transfer(low_per, low_src, dest, new_tip='never')
        p300m.drop_tip()

    # Step 4: Dilutions in mixing plate using ligand concentrations (2x), Row A-H, Col 1-N
    ligand_stock_high = reservoir1.wells()[0]
    ligand_stock_low = reservoir1.wells()[1]
    low_salt = reservoir0.wells()[0]

    cols = max(1, len(salt_list))
    rows = max(1, len(ligand_list))
    rows = min(rows, 8)

    vol_per_well = (total_vol / 2.0) * replicates * 1.5

    for col in range(cols):
        p300s.pick_up_tip()
        for row in range(rows):
            dest_well = mixing_plate.rows()[row][col]
            final_conc = 2.0 * ligand_list[row] if row < len(ligand_list) else 2.0 * ligand_list[-1]
            stock_vol = 0.0
            if stock_ligand > 0:
                stock_vol = vol_per_well * (final_conc / stock_ligand)
            stock_vol = max(0.0, min(stock_vol, vol_per_well))
            dest_vol = max(0.0, vol_per_well - stock_vol)
            if stock_vol > 0:
                p300s.transfer(stock_vol, ligand_stock_high, dest_well, new_tip='never')
            if dest_vol > 0:
                p300s.transfer(dest_vol, low_salt, dest_well, new_tip='never')
        p300s.drop_tip()

    protocol.comment('Template protocol with placeholders ready for substitution.')

